import { Children, type ReactNode, forwardRef, useEffect, useRef, useState } from 'react'
import { AccessibilityInfo } from 'react-native'
import { type TamaguiElement, View, isWeb } from 'tamagui/unstyled'
import { Button } from '../button/Button'
import { HStack, VStack } from '../layout/Stack'
import { ScrollArea, type ScrollAreaProps } from '../scroll-area/ScrollArea'
import { Spinner } from '../spinner/Spinner'
import { Text } from '../typography/Text'
import { VisuallyHidden } from '../visually-hidden/VisuallyHidden'
import { ariaState } from '../../utils/ariaState'
import { isTextContent } from '../../utils/isTextContent'
import { useNearEnd } from './useNearEnd'

export type InfiniteScrollMode = 'auto' | 'button'

export interface InfiniteScrollProps extends Omit<ScrollAreaProps, 'children' | 'orientation'> {
  /** The loaded items. Put them in directly, or give `itemCount`. */
  children: ReactNode
  /** More items remain to load. */
  hasMore: boolean
  /** A page is loading. The parent owns this state. */
  loading?: boolean
  /** Loads the next page: called near the end, or from the Load more button. */
  onLoadMore: () => void
  /** `auto` loads as the end comes near; `button` waits for Load more. Default `auto`. */
  mode?: InfiniteScrollMode
  /** How near the end loading starts, in visible heights. Default 0.5. */
  threshold?: number
  /** The number of loaded items. Default: the number of children. */
  itemCount?: number
  /** Why the last page failed. Shown with a Try again button; loading pauses until it clears. */
  error?: ReactNode
  /** Shown once nothing remains, such as "You're all caught up". */
  endMessage?: ReactNode
  loadingLabel?: string
  loadMoreLabel?: string
  retryLabel?: string
  /** Announced after a page loads, with the number of new items. */
  loadedLabel?: (count: number) => string
}

type Handler = (...args: never[]) => void

/** Our handlers first, then the caller's, such as `useBackToTop`'s onScroll. */
function mergeHandlers(own: Record<string, unknown>, extra: Record<string, unknown>) {
  const merged = { ...own }
  for (const [key, value] of Object.entries(extra)) {
    const theirs = own[key]
    merged[key] =
      typeof value === 'function' && typeof theirs === 'function'
        ? (...args: never[]) => {
            ;(value as Handler)(...args)
            ;(theirs as Handler)(...args)
          }
        : (theirs ?? value)
  }
  return merged
}

/**
 * Loads more items as the end of a list comes into view, with a loading
 * row, an error with Try again, and an end message. In a ScrollArea of its
 * own height, or on the page on web when it has none.
 */
export const InfiniteScroll = forwardRef<TamaguiElement, InfiniteScrollProps>(
  function InfiniteScroll(
    {
      children,
      hasMore,
      loading = false,
      onLoadMore,
      mode = 'auto',
      threshold = 0.5,
      itemCount,
      error,
      endMessage,
      loadingLabel = 'Loading more…',
      loadMoreLabel = 'Load more',
      retryLabel = 'Try again',
      loadedLabel = (count) => `${count} more loaded`,
      ...props
    },
    ref,
  ) {
    const count = itemCount ?? Children.count(children)
    const failed = error != null && error !== false
    const near = useNearEnd({
      enabled: mode === 'auto' && hasMore && !loading && !failed,
      threshold,
      count,
      onNearEnd: onLoadMore,
    })

    // After a page, say how many items came: on web through a live region,
    // on iOS and Android with announceForAccessibility.
    const [message, setMessage] = useState({ text: '', key: 0 })
    const announce = (text: string) => {
      if (isWeb) setMessage((current) => ({ text, key: current.key + 1 }))
      else AccessibilityInfo.announceForAccessibility(text)
    }
    const countBefore = useRef<number | null>(null)
    useEffect(() => {
      if (loading) {
        if (countBefore.current === null) countBefore.current = count
        return
      }
      if (countBefore.current === null) return
      const added = count - countBefore.current
      countBefore.current = null
      if (added > 0) announce(loadedLabel(added))
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [loading, count])
    useEffect(() => {
      if (typeof error === 'string' && error) announce(error)
    }, [error])

    let footer: ReactNode = null
    if (failed) {
      footer = (
        <VStack alignItems="center" gap="2" padding="3">
          {isTextContent(error) ? (
            <Text size="sm" tone="error" textAlign="center">
              {error}
            </Text>
          ) : (
            error
          )}
          <Button size="sm" variant="outline" onPress={onLoadMore}>
            {retryLabel}
          </Button>
        </VStack>
      )
    } else if (hasMore && mode === 'button') {
      footer = (
        <HStack justifyContent="center" padding="3">
          <Button
            size="sm"
            variant="outline"
            // Not `disabled` (nor LoadingButton, which sets it): a disabled
            // button drops keyboard focus, and this one is busy after each press.
            aria-disabled={ariaState(loading)}
            aria-busy={ariaState(loading)}
            icon={loading ? <Spinner size="sm" aria-hidden /> : undefined}
            onPress={() => {
              if (!loading) onLoadMore()
            }}
          >
            {loadMoreLabel}
          </Button>
        </HStack>
      )
    } else if (loading) {
      footer = (
        <HStack justifyContent="center" alignItems="center" gap="2" padding="3">
          {/* The text says what the spinner shows. */}
          <Spinner size="sm" aria-hidden />
          <Text size="sm" tone="muted">
            {loadingLabel}
          </Text>
        </HStack>
      )
    } else if (!hasMore && endMessage) {
      footer = (
        <HStack justifyContent="center" padding="3">
          {isTextContent(endMessage) ? (
            <Text size="sm" tone="muted" textAlign="center">
              {endMessage}
            </Text>
          ) : (
            endMessage
          )}
        </HStack>
      )
    }

    const setRefs = (node: TamaguiElement | null) => {
      near.frameRef.current = node
      if (typeof ref === 'function') ref(node)
      else if (ref) ref.current = node
    }

    return (
      <ScrollArea
        ref={setRefs}
        {...(loading && { 'aria-busy': true })}
        {...(mergeHandlers(props as Record<string, unknown>, near.frameProps) as object)}
      >
        <View>
          <View position="relative">
            {children}
            {near.sentinel}
          </View>
          {footer}
          {isWeb ? (
            <VisuallyHidden role="status" aria-live="polite">
              {message.text ? <Text key={message.key}>{message.text}</Text> : null}
            </VisuallyHidden>
          ) : null}
        </View>
      </ScrollArea>
    )
  },
)

import { useEffect, useRef, useState } from 'react'
import { type TamaguiElement, View } from 'tamagui/unstyled'

export interface NearEndOptions {
  /** Whether a load may start now: more to load, none loading, no error. */
  enabled: boolean
  /** How near the end counts, in visible heights. */
  threshold: number
  /** The number of loaded items, so a check after a render asks only once per length. */
  count: number
  onNearEnd: () => void
}

/**
 * Web: watches a sentinel at the end of the content with an
 * IntersectionObserver, which sees clipping by every scrolling box around
 * it, so the same code works in a ScrollArea of its own height or on the
 * page. The sentinel reaches up `threshold` visible heights from the end.
 */
export function useNearEnd({ enabled, threshold, count, onNearEnd }: NearEndOptions) {
  const frameRef = useRef<TamaguiElement | null>(null)
  const sentinelRef = useRef<TamaguiElement>(null)
  const [reach, setReach] = useState(0)
  const callback = useRef(onNearEnd)
  callback.current = onNearEnd
  const calledFor = useRef(-1)

  // The visible height: the area's own, or the window's when the page scrolls.
  useEffect(() => {
    const frame = frameRef.current as HTMLElement | null
    if (!frame) return
    const measure = () =>
      setReach(Math.round(threshold * Math.min(frame.clientHeight, window.innerHeight)))
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(frame)
    return () => observer.disconnect()
  }, [threshold])

  useEffect(() => {
    const sentinel = sentinelRef.current as HTMLElement | null
    if (!enabled || !sentinel || typeof IntersectionObserver === 'undefined') return
    let first = true
    const observer = new IntersectionObserver((entries) => {
      // The first report says where the end is now, after a render: load
      // only if the items changed since the last load, so a page that came
      // back empty does not load again and again.
      const initial = first
      first = false
      if (!entries.some((entry) => entry.isIntersecting)) return
      if (initial && calledFor.current === count) return
      calledFor.current = count
      callback.current()
    })
    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [enabled, count, reach])

  return {
    frameRef,
    frameProps: {},
    sentinel: (
      <View
        ref={sentinelRef}
        aria-hidden
        position="absolute"
        left={0}
        right={0}
        bottom={0}
        // At least a pixel, or there is nothing to intersect.
        height={Math.max(1, reach)}
        pointerEvents="none"
      />
    ),
  }
}

import { useRef } from 'react'
import type { LayoutChangeEvent, NativeScrollEvent, NativeSyntheticEvent } from 'react-native'
import type { TamaguiElement } from 'tamagui/unstyled'
import type { NearEndOptions } from './useNearEnd'

/**
 * Native: the ScrollView's own scroll, content size and layout. A check
 * after a render (a page loaded, or the area was laid out) asks only once
 * per length, as on web; a scroll by the user may always ask.
 */
export function useNearEnd({ enabled, threshold, count, onNearEnd }: NearEndOptions) {
  const frameRef = useRef<TamaguiElement | null>(null)
  const metrics = useRef({ offset: 0, content: 0, visible: 0 })
  const latest = useRef({ enabled, threshold, count, onNearEnd })
  latest.current = { enabled, threshold, count, onNearEnd }
  const calledFor = useRef(-1)

  const check = (byUser: boolean) => {
    const { offset, content, visible } = metrics.current
    const now = latest.current
    if (!now.enabled || visible === 0 || content === 0) return
    if (content - offset - visible > now.threshold * visible) return
    if (!byUser && calledFor.current === now.count) return
    calledFor.current = now.count
    now.onNearEnd()
  }

  // No check when `count` changes: the content size is still the old one
  // then, so it would load again. onContentSizeChange follows with the new.
  return {
    frameRef,
    frameProps: {
      onScroll: (event: NativeSyntheticEvent<NativeScrollEvent>) => {
        const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent
        metrics.current = {
          offset: contentOffset.y,
          content: contentSize.height,
          visible: layoutMeasurement.height,
        }
        check(true)
      },
      scrollEventThrottle: 16,
      // Content shorter than the area never scrolls: these fill it.
      onContentSizeChange: (_width: number, height: number) => {
        metrics.current.content = height
        check(false)
      },
      onLayout: (event: LayoutChangeEvent) => {
        metrics.current.visible = event.nativeEvent.layout.height
        check(false)
      },
    },
    sentinel: null,
  }
}

