import { Avatar, HStack, Text, VStack } from '@advui/core'
import { InfiniteScroll } from '@advui/data'
import { useEffect, useRef, useState } from 'react'

const people = ['Thiri Aung', 'Kyaw Zin', 'May Phyu', 'Htet Naing', 'Su Su']
const actions = ['updated the Bago sheet', 'commented on the 5W round', 'uploaded a map', 'closed a task']

const pageSize = 12
const pages = 4

const page = (n: number) =>
  Array.from({ length: pageSize }, (_, i) => {
    const index = n * pageSize + i
    return {
      id: index,
      who: people[index % people.length]!,
      what: actions[(index * 3) % actions.length]!,
      when: `${index + 2} min ago`,
    }
  })

export default function InfiniteScrollBasic() {
  const [items, setItems] = useState(() => page(0))
  const [loading, setLoading] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])

  const loadMore = () => {
    setLoading(true)
    // Stands in for a request to your API.
    timer.current = setTimeout(() => {
      setItems((current) => [...current, ...page(current.length / pageSize)])
      setLoading(false)
    }, 800)
  }

  return (
    <InfiniteScroll
      aria-label="Activity"
      height="80"
      width="100%"
      maxWidth="96"
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      hasMore={items.length < pageSize * pages}
      loading={loading}
      onLoadMore={loadMore}
      endMessage="You're all caught up"
    >
      {items.map((item) => (
        <HStack key={item.id} gap="3" alignItems="center" paddingHorizontal="4" paddingVertical="2-5">
          {/* The name follows in text. */}
          <Avatar
            size="sm"
            fallback={item.who
              .split(' ')
              .map((part) => part[0])
              .join('')}
            aria-hidden
          />
          <VStack flexShrink={1}>
            <Text size="sm">
              <Text size="sm" weight="medium">
                {item.who}
              </Text>{' '}
              {item.what}
            </Text>
            <Text size="xs" tone="muted">
              {item.when}
            </Text>
          </VStack>
        </HStack>
      ))}
    </InfiniteScroll>
  )
}

import { Separator, Text, VStack } from '@advui/core'
import { InfiniteScroll } from '@advui/data'
import { Fragment, useEffect, useRef, useState } from 'react'

const comments = [
  'The township totals match the July sheet now.',
  'Can we add the partner names to the map legend?',
  'Uploaded the corrected file.',
  'Thanks, that fixed the duplicate rows.',
  'Reviewed: ready to publish.',
]

const pageSize = 5

const page = (n: number) =>
  Array.from({ length: pageSize }, (_, i) => {
    const index = n * pageSize + i
    return { id: index, text: comments[index % comments.length]!, number: index + 1 }
  })

export default function InfiniteScrollLoadMore() {
  const [items, setItems] = useState(() => page(0))
  const [loading, setLoading] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])

  return (
    <InfiniteScroll
      aria-label="Comments"
      width="100%"
      maxWidth="96"
      mode="button"
      loadMoreLabel="Load more comments"
      hasMore={items.length < 20}
      loading={loading}
      onLoadMore={() => {
        setLoading(true)
        timer.current = setTimeout(() => {
          setItems((current) => [...current, ...page(current.length / pageSize)])
          setLoading(false)
        }, 800)
      }}
      endMessage="No more comments"
    >
      {items.map((item) => (
        <Fragment key={item.id}>
          <VStack gap="0-5" paddingVertical="2">
            <Text size="xs" tone="muted">
              Comment {item.number}
            </Text>
            <Text size="sm">{item.text}</Text>
          </VStack>
          <Separator />
        </Fragment>
      ))}
    </InfiniteScroll>
  )
}

import { HStack, Text } from '@advui/core'
import { InfiniteScroll } from '@advui/data'
import { useEffect, useRef, useState } from 'react'

const pageSize = 10

const page = (n: number) =>
  Array.from({ length: pageSize }, (_, i) => {
    const index = n * pageSize + i
    return { id: index, name: `Report ${String(index + 1).padStart(3, '0')}` }
  })

export default function InfiniteScrollError() {
  const [items, setItems] = useState(() => page(0))
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const failedOnce = useRef(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])

  const loadMore = () => {
    setError(null)
    setLoading(true)
    timer.current = setTimeout(() => {
      setLoading(false)
      // The second page fails the first time, as a dropped connection would.
      if (items.length === pageSize && !failedOnce.current) {
        failedOnce.current = true
        setError('Couldn’t load more reports. Check your connection.')
        return
      }
      setItems((current) => [...current, ...page(current.length / pageSize)])
    }, 800)
  }

  return (
    <InfiniteScroll
      aria-label="Reports"
      height="72"
      width="100%"
      maxWidth="80"
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      hasMore={items.length < 40}
      loading={loading}
      error={error}
      onLoadMore={loadMore}
      endMessage="All 40 reports"
    >
      {items.map((item) => (
        <HStack key={item.id} paddingHorizontal="4" paddingVertical="2-5">
          <Text size="sm">{item.name}</Text>
        </HStack>
      ))}
    </InfiniteScroll>
  )
}
